package com.bank.analytics.service;

import java.util.HashMap;
import java.util.Map;
import java.util.logging.Logger;

// Finds the longest run of distinct transaction channels in a session string.
public class ChannelSequenceAnalyzer {
    private static final Logger log = Logger.getLogger(ChannelSequenceAnalyzer.class.getName());

    // Returns the length of the longest substring with no repeating channel code.
    public int longestDistinctChannelRun(String session) {
        if (session == null || session.isEmpty()) {
            return 0;
        }
        Map<Character, Integer> lastSeen = new HashMap<>();
        int left = 0;
        int best = 0;

        for (int right = 0; right < session.length(); right++) {
            char channel = session.charAt(right);
            Integer prev = lastSeen.get(channel);
            // Only jump left if the duplicate is INSIDE the current window.
            if (prev != null && prev >= left) {
                final int newLeft = prev + 1;
                log.fine(() -> "Duplicate '" + channel + "' at " + right
                        + "; moving left to " + newLeft);
                left = newLeft;
            }
            lastSeen.put(channel, right);
            int windowLen = right - left + 1;
            if (windowLen > best) {
                best = windowLen;
                final int snapshot = best;
                log.fine(() -> "New best distinct run = " + snapshot);
            }
        }
        final int result = best;
        log.info(() -> "Longest distinct channel run = " + result);
        return result;
    }
}
