package com.bank.analytics;

import com.bank.analytics.model.Account;
import com.bank.analytics.service.ChannelSequenceAnalyzer;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class NoRepeatSubstringDemo {
    private static final Logger log = Logger.getLogger(NoRepeatSubstringDemo.class.getName());

    public static void main(String[] args) {
        setupLogging();

        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));
        Account priya = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000"));

        ChannelSequenceAnalyzer analyzer = new ChannelSequenceAnalyzer();

        // Rajesh's session: A=ATM U=UPI N=NEFT I=IMPS C=Card
        String rajeshSession = "AUNICAUN";
        log.info(() -> "Analyzing session for " + rajesh.getHolderName()
                + " (" + rajesh.getAccountId() + "): " + rajeshSession);
        int rajeshRun = analyzer.longestDistinctChannelRun(rajeshSession);
        log.info(() -> rajesh.getHolderName() + " longest distinct channel run = " + rajeshRun);

        String priyaSession = "UUNNIICC";
        log.info(() -> "Analyzing session for " + priya.getHolderName()
                + " (" + priya.getAccountId() + "): " + priyaSession);
        int priyaRun = analyzer.longestDistinctChannelRun(priyaSession);
        log.info(() -> priya.getHolderName() + " longest distinct channel run = " + priyaRun);
    }

    private static void setupLogging() {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.FINE);
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.FINE);
    }

    // Clean inline formatter so the demo prints readable logs.
    static class BankLogFormatter extends Formatter {
        @Override
        public String format(LogRecord r) {
            return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                    new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
        }
    }
}
